msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
msg.payload = {
  status: 'NODE_RED_GATEWAY_READY',
  gateway: 'leviagent-nodered',
  phase: 'job_tracker_pilot',
  google_sheets_pilot_enabled: true,
  enabled_flows: ['job_tracker_update']
};
return msg;

const adapter = global.get('jobTrackerGoogle');
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
try {
  const result = await adapter.invoke(msg.payload);
  msg.statusCode = 200;
  msg.payload = result;
} catch (error) {
  const code = String(error.code || 'FLOW_EXECUTION_FAILED');
  msg.statusCode = code === 'FLOW_IDEMPOTENCY_CONFLICT' || code === 'FLOW_RANGE_FULL' ? 409 : (code === 'FLOW_POLICY_REJECTED' ? 400 : 502);
  msg.payload = { status: code, flow: 'job_tracker_update', error: String(error.message || error).slice(0, 1000) };
}
return msg;
